DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Automation Console</title>
<style>
:root{--bg:#f7f8fc;--surface:#fff;--ink:#172033;--muted:#667085;--line:#e5e8f0;--brand:#635bff;--brand-dark:#4f46e5;--soft:#f0efff;--success:#087f5b;--danger:#b42318;--shadow:0 14px 42px rgba(27,37,72,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea{font:inherit}.shell{max-width:1200px;margin:auto;padding:28px 24px 56px}.nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:34px}.brand{display:flex;align-items:center;gap:11px;font-weight:760;font-size:17px}.mark{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:linear-gradient(135deg,#7c73ff,#5146dd);color:#fff;font-size:17px;box-shadow:0 7px 16px #635bff55}.environment{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:#12b76a}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;margin-bottom:25px}.eyebrow{color:var(--brand);font-weight:700;text-transform:uppercase;letter-spacing:.1em;font-size:11px;margin:0 0 9px}.hero h1{font-size:32px;letter-spacing:-.04em;margin:0 0 8px}.hero p{margin:0;color:var(--muted);max-width:600px;line-height:1.55}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:20px}.card{background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.card-head{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.card-head h2{font-size:15px;margin:0}.card-head span{font-size:12px;color:var(--muted)}.card-body{padding:22px}.auth{display:flex;gap:10px;align-items:center}.auth input{flex:1}.status{font-size:12px;color:var(--success);min-height:18px}.field{margin-bottom:16px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:7px;color:#344054}.field small{float:right;color:var(--muted);font-weight:400}.split{display:grid;grid-template-columns:1fr 1fr;gap:13px}input,textarea{width:100%;border:1px solid #d8ddea;border-radius:9px;padding:10px 11px;outline:none;color:var(--ink);background:#fff;transition:.15s}textarea{min-height:82px;resize:vertical}input:focus,textarea:focus{border-color:#8e89ff;box-shadow:0 0 0 3px #635bff18}.button{border:0;border-radius:9px;padding:10px 14px;background:var(--brand);color:#fff;font-weight:650;cursor:pointer;transition:.15s}.button:hover{background:var(--brand-dark);transform:translateY(-1px)}.button.secondary{background:#fff;color:#344054;border:1px solid #d8ddea}.button.danger{color:var(--danger)}.button:disabled{opacity:.55;cursor:not-allowed;transform:none}.hint{font-size:12px;line-height:1.5;color:var(--muted);margin:3px 0 0}.list{padding:4px 22px 10px}.job{padding:17px 0;border-bottom:1px solid var(--line)}.job:last-child{border:0}.job-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.job-name{font-weight:720;font-size:14px}.job-meta{font-size:12px;color:var(--muted);margin-top:5px}.badge{display:inline-flex;align-items:center;border-radius:99px;padding:4px 8px;font-size:11px;font-weight:700}.badge.live{background:#ecfdf3;color:#067647}.badge.off{background:#f2f4f7;color:#475467}.badge.failed{background:#fef3f2;color:var(--danger)}.job-prompt{color:#475467;line-height:1.45;margin:12px 0;font-size:13px}.job-footer{display:flex;align-items:center;justify-content:space-between;gap:10px}.last{font-size:12px;color:var(--muted);max-width:65%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:flex;gap:6px}.actions button{padding:6px 8px;font-size:12px}.empty{padding:42px 5px;text-align:center;color:var(--muted)}.empty b{display:block;color:#344054;margin-bottom:5px}.toast{position:fixed;right:22px;bottom:22px;background:#172033;color:#fff;padding:12px 15px;border-radius:10px;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:none}@media(max-width:850px){.grid{grid-template-columns:1fr}.hero{display:block}.hero h1{font-size:27px}.auth{margin-top:16px}.split{grid-template-columns:1fr}.shell{padding:20px 15px}.last{max-width:50%}}
</style></head><body><main class="shell"><nav class="nav"><div class="brand"><div class="mark">✦</div>Automation Console</div><div class="environment"><i class="dot"></i> Local workspace</div></nav><header class="hero"><div><p class="eyebrow">Scheduled publishing</p><h1>Build landing pages on your schedule.</h1><p>Create repeatable daily workflows. Lovable builds and publishes each resulting route.</p></div><div class="auth"><input id="key" type="password" placeholder="Control-panel API key"><button class="button secondary" onclick="connect()">Connect</button></div></header><div class="grid"><section class="card"><div class="card-head"><div><h2>Create automation</h2><span>A private, local scheduled workflow</span></div><span id="connection" class="status">Not connected</span></div><form class="card-body" onsubmit="createJob(event)"><div class="field"><label>Automation name</label><input id="name" required placeholder="Daily product launch page"></div><div class="split"><div class="field"><label>Schedule <small>cron</small></label><input id="cron" required value="0 9 * * *"></div><div class="field"><label>Timezone</label><input disabled value="Configured server timezone"></div></div><div class="field"><label>Daily brief</label><textarea id="prompt" required placeholder="For a fresh productivity topic, create an informative single-page landing page for..." ></textarea><p class="hint">Your saved idea and references are sent directly to Lovable when this job runs.</p></div><div class="field"><label>Reference sites <small>one URL per line</small></label><textarea id="refs" placeholder="https://example.com"></textarea></div><div class="split"><div class="field"><label>Image URLs <small>optional</small></label><textarea id="images" placeholder="https://..."></textarea></div><div class="field"><label>Links to include <small>optional</small></label><textarea id="links" placeholder="https://..."></textarea></div></div><button class="button" type="submit">Create automation</button></form></section><section class="card"><div class="card-head"><div><h2>Active automations</h2><span id="job-count">Connect to load schedules</span></div><button class="button secondary" onclick="load()">Refresh</button></div><div class="list" id="jobs"><div class="empty"><b>Your schedules will appear here</b>Connect with your control-panel key to manage them.</div></div></section></div></main><div class="toast" id="toast"></div><script>
const el=id=>document.getElementById(id),lines=id=>el(id).value.split('\n').map(x=>x.trim()).filter(Boolean);let jobsById={};const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function headers(){return {'Authorization':'Bearer '+localStorage.apiKey,'Content-Type':'application/json'}}function toast(msg){el('toast').textContent=msg;el('toast').classList.add('show');setTimeout(()=>el('toast').classList.remove('show'),2600)}function connect(){localStorage.apiKey=el('key').value;load()}async function request(path,options={}){const r=await fetch(path,{...options,headers:headers()});if(!r.ok){let b=await r.json().catch(()=>({}));throw Error(b.detail||'Request failed')}return r.status===204?null:r.json()}async function load(){if(!localStorage.apiKey)return;try{const jobs=await request('/automation/jobs');jobsById=Object.fromEntries(jobs.map(j=>[j.id,j]));el('connection').textContent='Connected';el('connection').style.color='var(--success)';el('job-count').textContent=`${jobs.length} schedule${jobs.length===1?'':'s'}`;el('jobs').innerHTML=jobs.length?jobs.map(jobView).join(''):`<div class="empty"><b>No automations yet</b>Create one from the form to begin.</div>`}catch(e){el('connection').textContent='Connection failed';el('connection').style.color='var(--danger)';toast(e.message)}}function jobView(j){const state=j.last_status==='failed'?'failed':j.enabled?'live':'off';const label=j.last_status==='failed'?'Needs attention':j.enabled?'Enabled':'Paused';return `<article class="job"><div class="job-top"><div><div class="job-name">${esc(j.name)}</div><div class="job-meta">${esc(j.cron)} · ${esc(j.last_run_at||'Never run')}</div></div><span class="badge ${state}">${label}</span></div><p class="job-prompt">${esc(j.prompt)}</p><div class="job-footer"><span class="last" title="${esc(j.last_detail||'')} ">${esc(j.last_detail||'Ready to run')}</span><div class="actions"><button class="button secondary" onclick="toggle('${j.id}')">${j.enabled?'Pause':'Enable'}</button><button class="button secondary" onclick="runNow('${j.id}')">Run now</button><button class="button secondary danger" onclick="removeJob('${j.id}')">Delete</button></div></div></article>`}async function createJob(e){e.preventDefault();try{await request('/automation/jobs',{method:'POST',body:JSON.stringify({name:el('name').value,cron:el('cron').value,prompt:el('prompt').value,reference_sites:lines('refs'),images:lines('images'),urls_to_include:lines('links'),enabled:true})});e.target.reset();el('cron').value='0 9 * * *';toast('Automation created');load()}catch(e){toast(e.message)}}async function toggle(id){let j={...jobsById[id],enabled:!jobsById[id].enabled};delete j.id;delete j.last_run_at;delete j.last_status;delete j.last_detail;try{await request('/automation/jobs/'+id,{method:'PUT',body:JSON.stringify(j)});toast(j.enabled?'Automation enabled':'Automation paused');load()}catch(e){toast(e.message)}}async function runNow(id){try{await request('/automation/jobs/'+id+'/run',{method:'POST'});toast('Run queued in the background');load()}catch(e){toast(e.message)}}async function removeJob(id){if(!confirm('Delete this automation?'))return;try{await request('/automation/jobs/'+id,{method:'DELETE'});toast('Automation deleted');load()}catch(e){toast(e.message)}}el('key').value=localStorage.apiKey||'';if(localStorage.apiKey)load();
</script></body></html>"""
